export type VaultsPluginPdas = {
  branch: typeof findBranchPda;
  position: typeof findPositionPda;
  positionMint: typeof findPositionMintPda;
  tickHasDebtArray: typeof findTickHasDebtArrayPda;
  vaultAdmin: typeof findVaultAdminPda;
  vaultConfig: typeof findVaultConfigPda;
  vaultMetadata: typeof findVaultMetadataPda;
  vaultState: typeof findVaultStatePda;
};

export type VaultsPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function vaultsProgram() {
  return <T extends VaultsPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { vaults: VaultsPlugin }> => {
    return extendClient(client, {
      vaults: <VaultsPlugin>{
        accounts: {
          branch: addSelfFetchFunctions(client, getBranchCodec()),
          dex: addSelfFetchFunctions(client, getDexCodec()),
          dexPosition: addSelfFetchFunctions(client, getDexPositionCodec()),
          oracle: addSelfFetchFunctions(client, getOracleCodec()),
          position: addSelfFetchFunctions(client, getPositionCodec()),
          tick: addSelfFetchFunctions(client, getTickCodec()),
          tickHasDebtArray: addSelfFetchFunctions(
            client,
            getTickHasDebtArrayCodec(),
          ),
          tickIdLiquidation: addSelfFetchFunctions(
            client,
            getTickIdLiquidationCodec(),
          ),
          tokenReserve: addSelfFetchFunctions(client, getTokenReserveCodec()),
          userBorrowPosition: addSelfFetchFunctions(
            client,
            getUserBorrowPositionCodec(),
          ),
          userSupplyPosition: addSelfFetchFunctions(
            client,
            getUserSupplyPositionCodec(),
          ),
          vaultAdmin: addSelfFetchFunctions(client, getVaultAdminCodec()),
          vaultConfig: addSelfFetchFunctions(client, getVaultConfigCodec()),
          vaultMetadata: addSelfFetchFunctions(client, getVaultMetadataCodec()),
          vaultState: addSelfFetchFunctions(client, getVaultStateCodec()),
        },
        instructions: {
          getExchangePrices: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getGetExchangePricesInstruction(input),
            ),
          initBranch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitBranchInstructionAsync(input),
            ),
          initPosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitPositionInstructionAsync(input),
            ),
          initTick: (input) =>
            addSelfPlanAndSendFunctions(client, getInitTickInstruction(input)),
          initTickHasDebtArray: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitTickHasDebtArrayInstructionAsync(input),
            ),
          initTickIdLiquidation: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitTickIdLiquidationInstruction(input),
            ),
          initVaultAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitVaultAdminInstructionAsync(input),
            ),
          initVaultConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitVaultConfigInstructionAsync(input),
            ),
          initVaultState: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitVaultStateInstructionAsync(input),
            ),
          liquidate: (input) =>
            addSelfPlanAndSendFunctions(client, getLiquidateInstruction(input)),
          liquidateDex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidateDexInstruction(input),
            ),
          liquidatePerfectDex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidatePerfectDexInstruction(input),
            ),
          operate: (input) =>
            addSelfPlanAndSendFunctions(client, getOperateInstruction(input)),
          operateDex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOperateDexInstruction(input),
            ),
          operatePerfectDex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOperatePerfectDexInstruction(input),
            ),
          rebalance: (input) =>
            addSelfPlanAndSendFunctions(client, getRebalanceInstruction(input)),
          rebalanceDex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRebalanceDexInstructionAsync(input),
            ),
          rebalanceDexWithAmounts: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRebalanceDexWithAmountsInstructionAsync(input),
            ),
          rebalanceWithAmounts: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRebalanceWithAmountsInstruction(input),
            ),
          updateAuthority: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateAuthorityInstruction(input),
            ),
          updateAuths: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateAuthsInstruction(input),
            ),
          updateBorrowFee: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateBorrowFeeInstruction(input),
            ),
          updateBorrowRateMagnifier: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateBorrowRateMagnifierInstruction(input),
            ),
          updateCollateralFactor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateCollateralFactorInstruction(input),
            ),
          updateCoreSettings: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateCoreSettingsInstruction(input),
            ),
          updateExchangePrices: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateExchangePricesInstruction(input),
            ),
          updateLiquidationMaxLimit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateLiquidationMaxLimitInstruction(input),
            ),
          updateLiquidationPenalty: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateLiquidationPenaltyInstruction(input),
            ),
          updateLiquidationThreshold: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateLiquidationThresholdInstruction(input),
            ),
          updateLookupTable: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateLookupTableInstruction(input),
            ),
          updateOracle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateOracleInstruction(input),
            ),
          updateRebalancer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateRebalancerInstruction(input),
            ),
          updateSupplyRateMagnifier: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateSupplyRateMagnifierInstruction(input),
            ),
          updateWithdrawGap: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateWithdrawGapInstruction(input),
            ),
        },
        pdas: {
          branch: findBranchPda,
          position: findPositionPda,
          positionMint: findPositionMintPda,
          tickHasDebtArray: findTickHasDebtArrayPda,
          vaultAdmin: findVaultAdminPda,
          vaultConfig: findVaultConfigPda,
          vaultMetadata: findVaultMetadataPda,
          vaultState: findVaultStatePda,
        },
        identifyAccount: identifyVaultsAccount,
        identifyInstruction: identifyVaultsInstruction,
        parseInstruction: parseVaultsInstruction,
      },
    });
  };
}
